71	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
72	 *                   accessible name is derived from the rendered title element automatically.
73	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
74	 *                   tab header). Paired with the floating close button by default. Pass
75	 *                   `boxedHeader` alongside it when the drawer has no header content of its own
76	 *                   to supply (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body)
77	 *                   but still wants the close button in the same in-flow header row `title` gets,
78	 *                   instead of floating over the content — the title `<span>` renders with no
79	 *                   text, purely to hold the close button's usual right-aligned position. The
80	 *                   drawer's accessible name still comes from `labelledBy`, unaffected.
81	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
82	 *                   is available.
83	 */
84	type ZimmDrawerProps = ZimmDrawerBaseProps &
85	  (
86	    | { title: string; labelledBy?: never; 'aria-label'?: never; boxedHeader?: never }
87	    | { title?: never; labelledBy: string; 'aria-label'?: never; boxedHeader?: boolean }
88	    | { title?: never; labelledBy?: never; 'aria-label': string; boxedHeader?: never }
89	  );
90	
91	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
92	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
93	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
94	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
95	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
96	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
97	type ZimmDrawerContentConfig = {
98	  children: React.ReactNode;
99	  onClose: () => void;
100	  /** Attached to the panel's own root element and used as the default `initialFocusRef` target
101	   *  (see ZimmDrawer's own comment on `panelRef` for why). */
102	  panelRef: React.RefObject<HTMLDivElement>;
103	  /** Renders an inline header row (title left, close button right) instead of the floating
104	   *  close button when provided — see ZimmDrawerProps' `title` member. */
105	  title?: string;
106	  titleId?: string;
107	  titleStyle?: 'large' | 'small';
108	  labelledBy?: string;
109	  ariaLabel?: string;
110	  /** Forces the same in-flow header row `title` renders (empty title span, close button in its
111	   *  usual right-aligned slot) instead of the floating close button — see ZimmDrawerProps'
112	   *  `labelledBy` member. Meaningless without `labelledBy`. */
113	  boxedHeader?: boolean;
114	  contentStyles: SystemStyleObject;
115	  headerStyles: SystemStyleObject;
116	  headerTitleStyles: SystemStyleObject;
117	  closeButtonStyles: SystemStyleObject;
118	  /** SFCC-831/689 rework — the boxed close button's own row (title/boxedHeader branch only),
119	   *  giving it a real 44px height to measure `header`'s paddingBlock-driven variants against.
120	   *  See zimmDrawer.css.ts's `headerCloseButton` for why the floating branch below doesn't
121	   *  need this (its own `closeButtonStyles` already sets an explicit height). */
122	  headerCloseButtonStyles: SystemStyleObject;
123	};
124	
125	/**
126	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
127	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
128	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
129	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
130	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
131	 *
132	 * Renders the inline header row (title left — empty when there's no `title` text — close button
133	 * right) when either `title` or `boxedHeader` is passed, or a floating close button only when
134	 * neither is — see ZimmDrawer's own docblock for when each is used.
135	 *
136	 * @param props see ZimmDrawerContentConfig
137	 */
138	const ZimmDrawerContent = ({
139	  children,
140	  onClose,
141	  title,
142	  titleId,
143	  titleStyle = 'large',
144	  labelledBy,
145	  ariaLabel,
146	  boxedHeader,
147	  contentStyles,
148	  headerStyles,
149	  headerTitleStyles,
150	  closeButtonStyles,
151	  panelRef,
152	  headerCloseButtonStyles,
153	}: ZimmDrawerContentConfig) => {
154	  const { t } = useUiCopy();
155	  const { getDialogProps, getDialogContainerProps } = useModalContext();
156	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
157	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
158	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
159	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
160	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
161	  if (title && titleId) {
162	    dialogProps['aria-labelledby'] = titleId;
163	  } else if (labelledBy) {
164	    dialogProps['aria-labelledby'] = labelledBy;
165	  }
166	  const containerProps = getDialogContainerProps();
167	
168	  return (
169	    <ModalFocusScope>
170	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
171	        <MotionChakraDiv
172	          {...dialogProps}
173	          initial={{ x: '100%' }}
174	          animate={{ x: 0 }}
175	          exit={{ x: '100%' }}
176	          transition={DRAWER_TRANSITION}
177	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
178	        >
179	          {/* Figma-fidelity audit fix, 2026-09-19: dedicated, invisible initial-focus sentinel —
180	              see ZimmDrawer's own `panelRef` comment for why this exists and why it isn't just
181	              `tabIndex={-1}` on the dialog element above instead. Putting it there was tried
182	              first and broke backdrop-click-to-close: Chakra's own overlay-click handler
183	              (`@chakra-ui/modal`'s `mouseDownTarget.current !== event.target` check) stopped
184	              matching once the dialog element itself became a focusable, focused target sharing
185	              the same boundary FocusLock/ModalFocusScope also tracks. A separate sentinel with no
186	              other role keeps the dialog element exactly as it was — untouched, non-focusable —
187	              while still giving `initialFocusRef` a real, invisible, non-interactive target. Zero
188	              size so it never affects layout; `aria-hidden` so it's invisible to assistive tech,
189	              which is correct here — it exists only to receive focus, it has nothing to announce. */}
190	          <chakra.div
191	            ref={panelRef}
192	            tabIndex={-1}
193	            aria-hidden="true"
194	            __css={{ position: 'absolute', width: 0, height: 0, overflow: 'hidden' }}
195	          />
196	          {title || boxedHeader ? (
197	            <chakra.div sx={headerStyles}>
198	              <chakra.span
199	                id={title ? titleId : undefined}
200	                sx={headerTitleStyles}
201	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
202	              >
203	                {title}
204	              </chakra.span>
205	              <chakra.div sx={headerCloseButtonStyles}>
206	                <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
207	              </chakra.div>
208	            </chakra.div>
209	          ) : (
210	            <chakra.div sx={closeButtonStyles}>
211	              <ZimmButton variant="icon" icon="close" label={t('drawer.close', 'Close')} onClick={onClose} />
212	            </chakra.div>
213	          )}
214	          {/* SFCC-926 — tester reported no scrollbar when drawer content exceeds the panel
215	              height. flex:1 + minHeight:0 lets this grow into remaining space after the
216	              fixed header; overflowY:auto gives it its own independent scrollbar. */}
217	          <chakra.div __css={{ flex: 1, overflowY: 'auto', minHeight: 0 }}>{children}</chakra.div>
218	        </MotionChakraDiv>
219	      </chakra.div>
220	    </ModalFocusScope>
221	  );
222	};
223	
224	/**
225	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
226	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
227	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
228	 * hand-rolled).
229	 *
230	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
231	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
232	 * that supply their own header (e.g. ZimmPdpDrawer's tab row) — the close button floats on its own
233	 * by default. Add `boxedHeader` alongside `labelledBy` when the drawer has no header content of its
234	 * own (e.g. ZimmCountryLanguageMismatch, whose heading lives in its body) but still wants the close
235	 * button sitting in that same in-flow header row rather than floating over the content.
236	 *
237	 * @param props see ZimmDrawerProps
238	 */
239	export const ZimmDrawer = (props: ZimmDrawerProps) => {
240	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
241	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
242	  const titleId = useId();
243	
244	  // Figma-fidelity audit fix, 2026-09-19: without an explicit `initialFocusRef`, Chakra's Drawer
245	  // defaults to auto-focusing the first focusable descendant — for every real consumer that
246	  // doesn't set one (ZimmCartDrawer, ZimmPdpDrawer), that's the close button. Reproduced live:
247	  // when nothing has focus and no prior user interaction exists yet (confirmed exactly matching
248	  // how a Storybook story that mounts already-open behaves, and plausible for a real first
249	  // render too), the browser's native `:focus-visible` heuristic has no basis to rule out a
250	  // keyboard interaction and defaults to showing the ring — on the close button, on every open,
251	  // regardless of whether the shopper used a mouse, touch, or keyboard to get there. `panelRef`
252	  // gives Chakra a neutral target instead: the dialog's own panel, `tabIndex={-1}` so it's
253	  // programmatically focusable without joining the normal Tab order. This still satisfies the
254	  // real requirement (focus moves into the dialog immediately, so keyboard/AT users land
255	  // somewhere sane and Tab/Escape work correctly from there) without ever auto-focusing an
256	  // interactive element nobody actually interacted with. A consumer that explicitly passes its
257	  // own `initialFocusRef` (ZimmWishlistAuthDrawer, straight to its email field) is untouched —
258	  // this only changes the *default* Chakra would otherwise have picked.
259	  const panelRef = useRef<HTMLDivElement>(null);
260	
261	  const title = 'title' in props ? props.title : undefined;
262	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
263	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
264	  const boxedHeader = !title && 'labelledBy' in props ? props.boxedHeader : undefined;
265	
266	  // SFCC-926 — tester reported body scroll still active while any drawer is open, allowing
267	  // the page behind the overlay to scroll alongside the drawer. ZimmDrawer bypasses Chakra's
268	  // own <DrawerContent>, so blockScrollOnMount may not fire. Locking body overflow explicitly
269	  // ensures only the drawer's internal scroll area is accessible while it is open.
270	  // Uses the module-level counter so multiple open instances don't race to restore overflow.
271	  useEffect(() => {
272	    if (!isOpen) return;
273	    if (scrollLockCount === 0) {
274	      scrollLockPrev = document.body.style.overflow;
275	      document.body.style.overflow = 'hidden';
276	    }
277	    scrollLockCount++;
278	    return () => {
279	      scrollLockCount--;
280	      if (scrollLockCount === 0) {
281	        document.body.style.overflow = scrollLockPrev;
282	        scrollLockPrev = '';
283	      }
284	    };
285	  }, [isOpen]);
286	
287	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
288	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
289	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
290	  // reliable moment to restore focus. Covers both close-button click and Escape for all
291	  // consumers that pass finalFocusRef.
292	  const handleCloseComplete = () => {
293	    if (finalFocusRef) finalFocusRef.current?.focus();
294	  };
295	
296	  return (
297	    <Drawer
298	      isOpen={isOpen}
299	      onClose={onClose}
300	      placement="right"
301	      onCloseComplete={handleCloseComplete}
302	      initialFocusRef={initialFocusRef ?? panelRef}
303	    >
304	      <DrawerOverlay sx={styles.overlay} />
305	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
306	          would clobber it with its own headingId (undefined without a DrawerHeader), but
307	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
308	          (see its own comment above) — the clobbering bug this would otherwise work around
309	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
310	      <ZimmDrawerContent
311	        onClose={onClose}
312	        title={title}
313	        titleId={title ? titleId : undefined}
314	        titleStyle={titleStyle}
315	        labelledBy={labelledBy}
316	        ariaLabel={ariaLabel}
317	        boxedHeader={boxedHeader}
318	        contentStyles={styles.content}
319	        headerStyles={styles.header}
320	        headerTitleStyles={styles.headerTitle}
321	        closeButtonStyles={styles.closeButton}
322	        panelRef={panelRef}
323	        headerCloseButtonStyles={styles.headerCloseButton}
324	      >
325	        {children}
326	      </ZimmDrawerContent>
327	    </Drawer>
328	  );
329	};
