183	  const styles = useStyleConfig('App');
184	  const { isOpen, onOpen, onClose } = useDisclosure();
185	  // SFCC-315 (plan step 9) — the raw state builder, not useCartDrawer()'s Context read: this
186	  // component is what mounts CartDrawerProvider below, so it cannot also consume its own
187	  // provided context (see useCartDrawer.ts's own module docblock, constraint 2). Called
188	  // directly here the same way useDisclosure() above already is, so onCartClick and every
189	  // nested consumer (product-view) share the identical live state, not two independent copies.
190	  const cartDrawer = useCartDrawerState();
191	
192	  // Determine Page Designer mode from URL - use req for server-side detection
193	  const pageDesignerMode = useMemo(() => {
194	    const queryParams = location?.search || '';
195	    if (queryParams.includes('mode=EDIT')) return 'EDIT';
196	    else if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW';
197	    return undefined;
198	    // matches upstream base _app exactly.
199	  }, [req?.url]);
200	
201	  const targetLocale = getTargetLocale({
202	    getUserPreferredLocales: () => {
203	      // CONFIG: This function should return an array of preferred locales. They can be
204	      // derived from various sources. Below are some examples of those:
205	      //
206	      // - client side: window.navigator.languages
207	      // - the page URL they're on (example.com/en-GB/home)
208	      // - cookie (if their previous preference is saved there)
209	      //
210	      // If this function returns an empty array (e.g. there isn't locale in the page url),
211	      // then the app would use the default locale as the fallback.
212	
213	      // NOTE: Your implementation may differ, this is just what we did.
214	      return [locale?.id || DEFAULT_LOCALE];
215	    },
216	    l10nConfig: site.l10n,
217	  });
218	
219	  // If the translation file exists, it'll be served directly from static folder (and won't reach this code here).
220	  // However, if the file is missing, the App would render a 404 page.
221	  const is404ForMissingTranslationFile = /\/static\/translations\/compiled\/[^.]+\.json$/.test(location?.pathname);
222	
223	  // Fetch the translation message data using the target locale.
224	  const { data: messages } = useQuery({
225	    queryKey: ['app', 'translations', 'messages', targetLocale],
226	    queryFn: () => {
227	      if (is404ForMissingTranslationFile) {
228	        // Return early to prevent an infinite loop
229	        // Otherwise, it'll continue to fetch the missing translation file again
230	        return {};
231	      }
232	      return fetchTranslations(targetLocale, appOrigin);
233	    },
234	    enabled: isServer,
235	  });
236	
237	  // Used to conditionally render header/footer for checkout page
238	  const isCheckout = /\/checkout$/.test(location?.pathname);
239	
240	  const { l10n } = site;
241	  // Get the current currency to be used through out the app
242	  const currency = locale.preferredCurrency || l10n.defaultCurrency;
243	
244	  // Handle creating a new basket if there isn't one already assigned to the current
245	  // customer.
246	  const { data: customer } = useCurrentCustomer();
247	  const { data: basket, dataUpdatedAt: basketQueryLastUpdateTime } = useCurrentBasket();
248	  const config = getConfig();
249	
250	  const updateBasket = useShopperBasketsMutation('updateBasket');
251	  const updateCustomerForBasket = useShopperBasketsMutation('updateCustomerForBasket');
252	
253	  useEffect(() => {
254	    // update the basket currency if it doesn't match the current locale currency
255	    if (basket?.currency && basket?.currency !== currency) {
256	      updateBasket.mutate({
257	        parameters: { basketId: basket.basketId },
258	        body: { currency },
259	      });
260	    }
261	    // matches upstream base _app exactly.
262	  }, [basket?.currency]);
263	
264	  const commerceAgentConfiguration = useMemo(() => {
265	    return getCommerceAgentConfig();
266	    // matches upstream base _app exactly.
267	  }, [config.app.commerceAgent]);
268	
269	  useEffect(() => {
270	    // update the basket customer email
271	    if (basket && customer?.isRegistered && customer?.email && customer?.email !== basket?.customerInfo?.email) {
272	      updateCustomerForBasket.mutate({
273	        parameters: { basketId: basket.basketId },
274	        body: {
275	          email: customer.email,
276	        },
277	      });
278	    }
279	    // matches upstream base _app exactly.
280	  }, [customer?.isRegistered, customer?.email, basket?.customerInfo?.email]);
281	
282	  useEffect(() => {
283	    // Listen for online status changes.
284	    watchOnlineStatus((online: boolean) => {
285	      setIsOnline(online);
286	    });
287	  }, []);
288	
289	  // Handle updating the shopper context
290	  useUpdateShopperContext();
291	
292	  useEffect(() => {
293	    // Lets automatically close the mobile navigation when the
294	    // location path is changed.
295	    onClose();
296	    // matches upstream base _app exactly.
297	  }, [location]);
298	
299	  // SFCC-885: the mobile drawer's isOpen state above is otherwise only ever closed by route
300	  // changes (the effect above) or an explicit close control — nothing closes it on a resize or
301	  // orientation change. That's a real gap, not a hardening: DrawerMenu renders a Chakra
302	  // <Drawer>, which always portals its content straight to document.body, so HideOnDesktop's
303	  // display:none on its wrapper (below) never actually hides an already-open drawer once the
304	  // viewport crosses into desktop width — the drawer keeps rendering full-screen on top of the
305	  // now-visible desktop nav. Closing it here whenever the viewport is no longer mobile (same
306	  // MOBILE_DESKTOP_SPLIT the HideOnDesktop/HideOnMobile split below already uses) fixes that for
307	  // every way the crossing can happen, not just a device rotation.
308	  const isMobileViewport = useBreakpointValue({ base: true, [MOBILE_DESKTOP_SPLIT]: false });
309	  useEffect(() => {
310	    if (isMobileViewport === false) onClose();
311	  }, [isMobileViewport]);
312	
313	  const onLogoClick = (): void => {
314	    // Goto the home page.
315	    const path = buildUrl(HOME_HREF);
316	
317	    history.push(path);
318	
319	    // Close the drawer.
320	    onClose();
321	  };
322	
323	  // SFCC-315 (plan step 9) — opens the cart drawer instead of navigating to the base `/cart`
324	  // route. `Header`/`RightBar` thread `onMyCartClick` straight through to the real
325	  // `IconButton`'s `onClick` prop unwrapped (`header/index.tsx`'s `onMyCartClick={onMyCartClick}`,
326	  // `header/rightBar/index.tsx`'s `onClick={onMyCartClick}` on both the desktop and mobile bag
327	  // icons) — verified directly, not assumed — so this function is the literal handler React
328	  // invokes on click, and receives the real click SyntheticEvent as its argument even though
329	  // every intermediate prop type along that chain still declares `() => void`. That lets this
330	  // capture the actual clicked icon as the AC10 focus-return trigger with no change needed to
331	  // either header file.
332	  const onCartClick = (e?: React.SyntheticEvent<HTMLElement>): void => {
333	    cartDrawer.onOpen(e?.currentTarget ?? null);
334	
335	    // Close the mobile nav drawer if it happened to be open — unrelated to the cart drawer,
336	    // unchanged from this handler's pre-existing behaviour.
337	    onClose();
338	  };
339	
340	  const onAccountClick = (): void => {
341	    // Link to account page if registered; Header component will show auth modal for guest users
342	    const path = buildUrl('/account');
343	    history.push(path);
344	  };
345	
346	  const onWishlistClick = (): void => {
347	    // Link to wishlist page if registered; Header component will show auth modal for guest users
348	    const path = buildUrl('/account/wishlist');
349	    history.push(path);
350	  };
351	
352	  const { actions: shopperAgentActions } = useShopperAgent();
353	
354	  const trackPage = (): void => {
355	    activeData.trackPage(site.id, locale.id, currency);
356	  };
357	
358	  useEffect(() => {
359	    trackPage();
360	    // matches upstream base _app exactly.
361	  }, [location]);
362	
363	  const getHrefForLocale = (localeId: string): string =>
364	    `${appOrigin}${getRouterBasePath()}${getPathWithLocale(localeId, buildUrl, {
365	      location: { ...location, search: '' },
366	    })}`;
367	
368	  return (
369	    <Box className="sf-app" {...styles.container}>
370	      <StorefrontPreview getToken={getTokenWhenReady} getBasePath={getRouterBasePath}>
371	        <IntlProvider
372	          onError={(err) => {
373	            if (!messages) {
374	              // During the ssr prepass phase the messages object has not loaded, so we can suppress
375	              // errors during this time.
376	              return;
377	            }
378	            if (err.code === 'MISSING_TRANSLATION') {
379	              // NOTE: Remove the console error for missing translations during development,
380	              // as we knew translations would be added later.
381	              logger.warn('Missing translation', {
382	                namespace: 'App.IntlProvider',
383	                additionalProperties: {
384	                  errorMessage: err.message,
385	                },
386	              });
387	              return;
388	            }
389	            throw err;
390	          }}
391	          locale={targetLocale}
392	          messages={messages}
393	          // For react-intl, the _default locale_ refers to the locale that the inline `defaultMessage`s are written for.
394	          // NOTE: if you update this value, please also update the following npm scripts in `template-retail-react-app/package.json`:
395	          // - "extract-default-translations"
396	          // - "compile-translations:pseudo"
397	          defaultLocale={DEFAULT_LOCALE}
398	        >
399	          <CurrencyProvider currency={currency}>
400	            <Seo>
401	              <meta name="theme-color" content={THEME_COLOR} />
402	              <meta name="apple-mobile-web-app-title" content={DEFAULT_SITE_TITLE} />
403	              <link rel="apple-touch-icon" href={getAssetUrl('static/img/global/apple-touch-icon.png')} />
404	              <link rel="manifest" href={getAssetUrl('static/manifest.json')} />
405	
406	              {/* Urls for all localized versions of this page (including current page)
407	              For more details on hrefLang, see https://developers.google.com/search/docs/advanced/crawling/localized-versions */}
408	              {site.l10n?.supportedLocales.map((l: { id: string }) => (
409	                <link rel="alternate" hrefLang={l.id.toLowerCase()} href={getHrefForLocale(l.id)} key={l.id} />
410	              ))}
411	              {/* A general locale as fallback. For example: "en" if default locale is "en-GB" */}
412	              <link rel="alternate" hrefLang={site.l10n.defaultLocale.slice(0, 2)} href={getHrefForLocale(locale.id)} />
413	              {/* A wider fallback for user locales that the app does not support */}
414	              <link rel="alternate" hrefLang="x-default" href={`${appOrigin}/`} />
415	            </Seo>
416	
417	            {commerceAgentConfiguration?.enabled === 'true' && (
418	              <ShopperAgent
419	                commerceAgentConfiguration={commerceAgentConfiguration}
420	                basketDoneLoading={basketQueryLastUpdateTime > 0}
421	              />
422	            )}
423	
424	            <ScrollToTop />
425	
426	            <Box id="app" display="flex" flexDirection="column" flex={1}>
427	              <SkipNavLink zIndex="skipLink">Skip to Content</SkipNavLink>
428	              {storeLocatorEnabled && <StoreLocatorModal isOpen={isStoreLocatorOpen} onClose={onCloseStoreLocator} />}
429	              <Island hydrateOn={'visible'}>
430	                <Box {...styles.headerWrapper}>
431	                  {!isCheckout ? (
432	                    <>
433	                      <AboveHeader />
434	                      <Header
435	                        onMenuClick={onOpen}
436	                        onLogoClick={onLogoClick}
437	                        onMyCartClick={onCartClick}
438	                        onMyAccountClick={onAccountClick}
439	                        onWishlistClick={onWishlistClick}
440	                        onStoreLocatorClick={onOpenStoreLocator}
441	                        onAgentClick={shopperAgentActions.open}
442	                      >
443	                        <HideOnDesktop>
444	                          <DrawerMenu
445	                            isOpen={isOpen}
446	                            onClose={onClose}
447	                            onLogoClick={onLogoClick}
448	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
449	                            itemsKey="categories"
450	                            itemsCountKey="onlineSubCategoriesCount"
451	                            itemComponent={DrawerMenuItemWithData}
452	                          />
453	                        </HideOnDesktop>
454	
455	                        <HideOnMobile>
456	                          <ListMenu
457	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
458	                            itemsKey="categories"
459	                            itemsCountKey="onlineSubCategoriesCount"
460	                            contentComponent={ListMenuContentWithData}
461	                          />
462	                        </HideOnMobile>
463	                      </Header>
464	                    </>
465	                  ) : (
466	                    <CheckoutHeader />
467	                  )}
468	                </Box>
469	              </Island>
470	              {!isOnline && <OfflineBanner />}
471	              <CartDrawerProvider value={cartDrawer}>
472	                <BonusProductSelectionModalProvider>
473	                  <SkipNavContent
474	                    style={{
475	                      display: 'flex',
476	                      flexDirection: 'column',
477	                      flex: 1,
478	                      outline: 0,
479	                    }}
480	                  >
481	                    <Box as="main" id="app-main" role="main" display="flex" flexDirection="column" flex="1">
482	                      <OfflineBoundary isOnline={false}>
483	                        <PageDesignerProvider
484	                          clientId="pwa-kit-client"
485	                          targetOrigin="*"
486	                          usid={usid ?? undefined}
487	                          mode={pageDesignerMode}
488	                        >
489	                          <PageDesignerInit />
490	                          {children}
491	                        </PageDesignerProvider>
492	                      </OfflineBoundary>
493	                    </Box>
494	                  </SkipNavContent>
495	
496	                  <Island hydrateOn={'visible'}>{!isCheckout ? <Footer /> : <CheckoutFooter />}</Island>
497	
498	                  <AuthModal {...authModal} />
499	                  <ZimmLanguagePrompt site={site} locale={locale} buildUrl={buildUrl} />
500	                </BonusProductSelectionModalProvider>
501	              </CartDrawerProvider>
502	            </Box>
503	          </CurrencyProvider>
504	        </IntlProvider>
505	      </StorefrontPreview>
506	    </Box>
507	  );
508	};
509	
510	export default App;
511

